.filters .fgroup {
  line-height: 22.475px;
}"},"evidenceCited":["box.chromium","box.firefox","box.webkit","computedStylesSameInAllThree.fontSize","computedStylesThatDiffer.lineHeight","computedStylesThatDiffer.height","ancestors.1","otherSurvivorsOnThisPage","inspect_element(DIV[4]).firefox.ry"],"unresolved":[]}

